# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, floor_=6):
    return [v for v in xs if v > floor_]

# region: digest
def digest(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: gather
def gather(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(digest(sift(render(shape(emit(raw))))))

